  "settings.modelProvider.fieldHelp": "Про {field}",
  "settings.modelProvider.help.contextWindow": "Обсяг контексту, який модель може обробити одночасно, у токенах. ZAICODE використовує це для керування контекстом.\nНе перевищуйте фактичної межі моделі.",
  "settings.modelProvider.help.maxOutputTokens": "Максимальна кількість токенів, яку може згенерувати один запит до моделі.\nНе перевищуйте фактичної межі моделі.",
  "settings.modelProvider.help.inputModalities": "Визначте типи вмісту, які модель може отримувати:\n\n- **Текст**: Отримує текстовий вміст. Обов'язковий.\n- **Зображення**: Отримує зображення.\n- **Відео**: Отримує відео.\n- **PDF**: Отримує PDF-документи напряму.",
  "settings.modelProvider.help.outputModalities": "Тип вмісту відповідей моделі. Наразі підтримується лише текст.",
  "settings.modelProvider.help.capabilities": "- **Структурований вивід**: Підтримує обмеження JSON Schema для полів, типів і структури виводу.\n- **Вбудований веб-пошук**: Підтримує вбудовану можливість веб-пошуку в API моделі.\n- **Системні повідомлення посеред розмови**: Підтримує вставлення системних інструкцій під час розмови.\n\nНе вмикайте можливості, які модель не підтримує.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Визначте рівні міркування, доступні в чаті. **Їх має бути впорядковано від найнижчого до найвищого рівня міркування**.\nНе налаштовуйте рівні міркування, які модель не підтримує.",
  "settings.modelProvider.help.reasoningLevelMapping": "Використайте вираз CEL, щоб відобразити поточний рівень міркування `reasoningLevel` на поля запиту до API моделі. JSON-об'єкт, повернутий виразом, об'єднується з тілом запиту.",
  "settings.modelProvider.help.advanced": "**MFJS-схема інструментів**: Увімкнює сумісність із Moonshot Flavored JSON Schema, яку зазвичай використовує API моделей Kimi від Moonshot. Увімкніть лише тоді, коли API моделі вимагає цього формату.",
  "settings.modelProvider.help.followRecommendedConfig": "Відповідає рекомендованій конфігурації за ID моделі, Base URL і форматом API. ZAICODE постійно оновлює рекомендації й автоматично синхронізує їх.\nКоли ви змінюєте налаштування вручну, воно переходить у ручний режим і більше не оновлюється за рекомендаціями; інші налаштування й далі керуються розумною конфігурацією.",
